  matched integer;
begin
  -- Lock exactly this batch, and fail rather than overwrite concurrent editorial work.
  perform r.id from public.recipes r
    join jsonb_to_recordset(plan) as p(id uuid, old_path text, new_path text, preserved_hash text) on r.id=p.id
    for update of r;
  select count(*) into matched from public.recipes r
    join jsonb_to_recordset(plan) as p(id uuid, old_path text, new_path text, preserved_hash text) on r.id=p.id
    where r.public_path=p.old_path and md5((to_jsonb(r)-'public_path'-'updated_at')::text)=p.preserved_hash;
  if matched<>63 then raise exception 'Route/content snapshot changed: expected 63, found %',matched; end if;
  if exists (
    select 1 from jsonb_to_recordset(plan) as p(id uuid, new_path text)
    join public.recipes r on rtrim(r.public_path,'/')=rtrim(p.new_path,'/') and r.id<>p.id
  ) or exists (
    select 1 from jsonb_to_recordset(plan) as p(new_path text)
    join public.content_pages c on rtrim(c.public_path,'/')=rtrim(p.new_path,'/')
  ) or exists (
    select 1 from jsonb_to_recordset(plan) as p(new_path text)
    join public.content_redirects d on rtrim(d.source_path,'/')=rtrim(p.new_path,'/')
  ) then raise exception 'Target URL collision'; end if;
  update public.recipes r set public_path=p.new_path
    from jsonb_to_recordset(plan) as p(id uuid, new_path text) where r.id=p.id;
  get diagnostics matched = row_count;
  if matched<>63 then raise exception 'Unexpected update count %',matched; end if;
  if exists (
    select 1 from public.recipes r
    join jsonb_to_recordset(plan) as p(id uuid, new_path text, preserved_hash text) on r.id=p.id
    where r.public_path<>p.new_path or md5((to_jsonb(r)-'public_path'-'updated_at')::text)<>p.preserved_hash
  ) then raise exception 'Preservation invariant failed'; end if;
end $$;
commit;
